import java.util.*;

public class Main {
    static long maxSumMinProduct(int[] nums) {
        long MOD = 1_000_000_007L;
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        int[] leftSmaller = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) stack.pop();
            leftSmaller[i] = stack.isEmpty() ? -1 : stack.peek();     // nearest strictly smaller, to the left
            stack.push(i);
        }
        int[] rightSmaller = new int[n];
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) stack.pop();
            rightSmaller[i] = stack.isEmpty() ? n : stack.peek();     // nearest strictly smaller, to the right
            stack.push(i);
        }
        long best = 0;
        for (int i = 0; i < n; i++) {
            long spanSum = prefix[rightSmaller[i]] - prefix[leftSmaller[i] + 1];  // O(1) span sum
            best = Math.max(best, nums[i] * spanSum);
        }
        return best % MOD;
    }
}

