#include <bits/stdc++.h>
using namespace std;

long long maxSumMinProduct(vector<int>& nums) {
    const long long MOD = 1000000007;
    int n = nums.size();
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    vector<int> leftSmaller(n, -1), rightSmaller(n, n);
    vector<int> stack;
    for (int i = 0; i < n; i++) {
        while (!stack.empty() && nums[stack.back()] >= nums[i]) stack.pop_back();
        leftSmaller[i] = stack.empty() ? -1 : stack.back();      // nearest strictly smaller, to the left
        stack.push_back(i);
    }
    stack.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.empty() && nums[stack.back()] >= nums[i]) stack.pop_back();
        rightSmaller[i] = stack.empty() ? n : stack.back();      // nearest strictly smaller, to the right
        stack.push_back(i);
    }
    long long best = 0;
    for (int i = 0; i < n; i++) {
        long long spanSum = prefix[rightSmaller[i]] - prefix[leftSmaller[i] + 1];  // O(1) span sum
        best = max(best, (long long)nums[i] * spanSum);
    }
    return best % MOD;
}
